import socketfrom ast import literal_evalfrom GUI.kv import ip_addressfrom lib.utility.util import chessboard# from GUI.kv import new_playerclient_s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)chess_temp = chessboardmsg = bytes(str(chessboard), 'utf-8')client_s.sendto(msg, (ip_address, 12345))print('[Data send]')data, addr = client_s.recvfrom(4096)print("[Data received]")data = eval(data)print(data, type(data))if data != chessboard:    chessboard = dataclient_s.close()